import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import {
  Activity, ArrowDownLeft, ArrowDownToLine, ArrowLeft, ArrowLeftRight, ArrowRight, ArrowUpRight,
  Bell, Box, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Download, Eye,
  EyeOff, FileClock, Flag, FlaskConical, Info, LayoutGrid, LoaderCircle, LogOut, Menu, Package,
  Plus, RefreshCw, Search, ShieldCheck, SlidersHorizontal, Smartphone, TriangleAlert, UserRound,
  Users, Warehouse as WarehouseIcon, Wifi, WifiOff, X,
} from 'lucide-react';
import { api, ApiError, errorMessage, readPendingOperation, savePendingOperation } from './api';
import { Alert, Badge, Brand, dateLabel, Dialog, Empty, Field, OperationBadge, operationLabel, OperationResult, quantityLabel, Spinner, terminalStates, timestampLabel } from './components';
import type { AuthResponse, HistoryItem, Operation, Page, Part, ProblemCategory, ProblemReport, Role, StockItem, User, View, Warehouse } from './types';

const roleLabels: Record<Role, string> = { medic: 'Ratownik medyczny', warehouse_manager: 'Magazynier', admin: 'Administrator' };
const categoryLabels: Record<ProblemCategory, string> = { damage: 'Uszkodzenie', expired: 'Przeterminowanie', discrepancy: 'Rozbieżność', other: 'Inny problem' };
const viewTitles: Record<View, string> = { stock: 'Mój magazyn', history: 'Historia operacji', reports: 'Zgłoszenia', movements: 'Operacje magazynowe', review: 'Uzgadnianie operacji', users: 'Zespół i uprawnienia', account: 'Moje konto' };
const allowedViews = new Set<View>(['stock', 'history', 'reports', 'movements', 'review', 'users', 'account']);
function currentView(): View { const value = window.location.hash.slice(1) as View; return allowedViews.has(value) ? value : 'stock'; }
function navigate(view: View) { window.location.hash = view; }
function isManager(user: User) { return user.role !== 'medic'; }

function useOnline() {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => { const update = () => setOnline(navigator.onLine); window.addEventListener('online', update); window.addEventListener('offline', update); return () => { window.removeEventListener('online', update); window.removeEventListener('offline', update); }; }, []);
  return online;
}

function useResource<T>(load: () => Promise<T>, dependencies: unknown[]) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [iteration, setIteration] = useState(0);
  useEffect(() => {
    let active = true;
    setLoading(true); setError('');
    void load().then((value) => { if (active) setData(value); }).catch((reason: unknown) => { if (active) { setError(errorMessage(reason)); setData(null); } }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [...dependencies, iteration]);
  return { data, error, loading, reload: () => setIteration((value) => value + 1) };
}

export function App() {
  const [user, setUser] = useState<User | null>(null);
  const userRef = useRef<User | null>(null);
  const [initializing, setInitializing] = useState(true);
  const [sessionMessage, setSessionMessage] = useState('');
  const [view, setView] = useState<View>(currentView);
  const [revision, setRevision] = useState(0);
  const [pendingId, setPendingId] = useState<string | null>(readPendingOperation);
  const [operation, setOperation] = useState<Operation | null>(null);
  const [checking, setChecking] = useState(false);
  const [toast, setToast] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const online = useOnline();
  const resetToken = useRef<string | null>(null);
  const resetPage = useRef(window.location.pathname === '/reset-password');
  if (resetPage.current && resetToken.current === null) {
    resetToken.current = new URLSearchParams(window.location.hash.slice(1)).get('token') ?? '';
    if (window.location.hash) window.history.replaceState(null, '', '/reset-password');
  }
  useEffect(() => {
    api.onUnauthorized = () => { if (userRef.current) { userRef.current = null; setUser(null); setOperation(null); setSessionMessage('Twoja sesja wygasła. Zaloguj się ponownie, aby kontynuować.'); api.clear(); void api.csrf().catch(() => {}); } };
    let active = true;
    void api.request<AuthResponse>('/api/me').then((response) => { if (active) { api.setCsrfToken(response.csrfToken); userRef.current = response.user; setUser(response.user); } }).catch(() => api.csrf().catch(() => {})).finally(() => { if (active) setInitializing(false); });
    return () => { active = false; api.onUnauthorized = undefined; };
  }, []);
  useEffect(() => { const update = () => { setView(currentView()); setMenuOpen(false); }; window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update); }, []);
  useEffect(() => { document.title = `${viewTitles[view]} · MEDAM`; }, [view]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 6500); return () => clearTimeout(timer); }, [toast]);
  const setPending = useCallback((id: string | null) => { savePendingOperation(id); setPendingId(id); }, []);
  const handleOperation = useCallback((result: Operation) => { setOperation(result); setPending(terminalStates.has(result.state) ? null : result.id); setRevision((value) => value + 1); }, [setPending]);
  const checkOperation = useCallback(async (id: string) => {
    setChecking(true);
    try { handleOperation(await api.request<Operation>(`/api/operations/${id}`)); }
    catch (error) { if (error instanceof ApiError && error.status === 404) { setToast('Operacja nie jest jeszcze dostępna dla tego konta. Nie powtarzaj zapisu; sprawdź ponownie lub skontaktuj się z administratorem.'); } else setToast(errorMessage(error)); }
    finally { setChecking(false); }
  }, [handleOperation, setPending]);
  useEffect(() => { if (user && pendingId) void checkOperation(pendingId); }, [user?.id]);

  async function logout() {
    setLoggingOut(true);
    try { await api.request('/api/auth/logout', { method: 'POST', body: {} }); userRef.current = null; setUser(null); setPending(null); setOperation(null); api.clear(); await api.csrf(); setSessionMessage('Wylogowano bezpiecznie.'); }
    catch (error) { setToast(errorMessage(error)); }
    finally { setLoggingOut(false); }
  }

  if (resetPage.current) return <PasswordReset token={resetToken.current ?? ''} online={online} />;
  if (initializing) return <div className="boot"><Brand /><Spinner label="Sprawdzanie sesji…" /></div>;
  if (!user) return <Login online={online} message={sessionMessage} onLogin={(response) => { api.setCsrfToken(response.csrfToken); userRef.current = response.user; setUser(response.user); setSessionMessage(''); navigate('stock'); }} />;

  const title = view === 'stock' && isManager(user) ? 'Magazyny' : viewTitles[view];
  const navigation: { view: View; label: string; icon: ReactNode }[] = [
    { view: 'stock', label: isManager(user) ? 'Magazyny' : 'Mój magazyn', icon: <LayoutGrid size={20} /> },
    ...(isManager(user) ? [{ view: 'movements' as View, label: 'Operacje magazynowe', icon: <ArrowLeftRight size={20} /> }] : []),
    { view: 'history', label: 'Historia operacji', icon: <FileClock size={20} /> },
    { view: 'reports', label: 'Zgłoszenia', icon: <Flag size={20} /> },
    ...(user.role === 'admin' ? [{ view: 'review' as View, label: 'Uzgadnianie operacji', icon: <ShieldCheck size={20} /> }, { view: 'users' as View, label: 'Zespół', icon: <Users size={20} /> }] : []),
  ];
  const permitted = navigation.some((item) => item.view === view) || view === 'account';

  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`} aria-label="Menu główne"><a href="#stock" className="brand-link" aria-label="MEDAM — magazyn"><Brand /></a><div className="workspace-label">PRZESTRZEŃ ZESPOŁU</div><nav>{navigation.map((item) => <a key={item.view} className={`nav-item ${view === item.view ? 'nav-active' : ''}`} href={`#${item.view}`} aria-current={view === item.view ? 'page' : undefined}>{item.icon}<span>{item.label}</span>{view === item.view && <span className="nav-dot" />}</a>)}</nav><div className="sidebar-note"><div className="sidebar-note-icon"><ShieldCheck size={22} /></div><strong>Właściwy preparat.<br />Pełna kontrola.</strong><p>Każda zmiana ma swój ślad w historii magazynu.</p></div><button className={`sidebar-account ${view === 'account' ? 'account-active' : ''}`} onClick={() => navigate('account')}><span className="avatar">{user.login.slice(0, 2).toUpperCase()}</span><span className="account-label"><strong>{user.login}</strong><small>{roleLabels[user.role]}</small></span><ChevronRight size={17} /></button></aside>
    {menuOpen && <button className="menu-scrim" aria-label="Zamknij menu" onClick={() => setMenuOpen(false)} />}
    <div className="main-shell"><header className="topbar"><div className="topbar-start"><button className="icon-button mobile-menu" onClick={() => setMenuOpen(true)} aria-label="Otwórz menu"><Menu size={22} /></button><span className="topbar-section">Magazyn medyczny</span><span className="topbar-separator">/</span><span className="topbar-current">{title}</span></div><div className="topbar-end"><span className={`connection ${online ? '' : 'connection-offline'}`}>{online ? <span className="status-dot" /> : <WifiOff size={14} />}<span>{online ? 'Połączono' : 'Brak sieci'}</span></span><span className="topbar-divider" /><button className="icon-button" onClick={() => navigate('account')} aria-label="Moje konto"><UserRound size={19} /></button></div></header>
      <main className="main" id="main-content"><div className="page-topline"><span className="eyebrow">TWOJA PRZESTRZEŃ PRACY</span><span className="today-label">{new Intl.DateTimeFormat('pl-PL', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Warsaw' }).format(new Date())}</span></div>
        {!online && <Alert kind="warning">Brak połączenia z internetem. Zapisy magazynowe są niedostępne. Po powrocie sieci odśwież dane.</Alert>}
        {pendingId && <Alert kind="warning" action={<button className="text-button" disabled={checking || !online} onClick={() => void checkOperation(pendingId)}>{checking ? 'Sprawdzanie…' : 'Sprawdź status'}<ChevronRight size={16} /></button>}><strong>Poprzednia operacja wymaga sprawdzenia.</strong><p>Nie wprowadzaj jej ponownie. Identyfikator: <code>{pendingId}</code></p></Alert>}
        {!permitted ? <Empty title="Ten widok jest niedostępny">Twoje konto nie ma uprawnień do tej części aplikacji.<button className="text-button" onClick={() => navigate('stock')}>Przejdź do magazynu<ArrowRight size={16} /></button></Empty> : <>
          {view === 'stock' && <StockPage user={user} online={online} revision={revision} pendingId={pendingId} onPending={setPending} onOperation={handleOperation} onToast={setToast} />}
          {view === 'history' && <HistoryPage user={user} revision={revision} onOperation={(id) => void checkOperation(id)} onToast={setToast} />}
          {view === 'reports' && <ReportsPage user={user} online={online} revision={revision} onToast={setToast} />}
          {view === 'movements' && isManager(user) && <MovementsPage online={online} pendingId={pendingId} onPending={setPending} onOperation={handleOperation} />}
          {view === 'review' && user.role === 'admin' && <ReviewPage online={online} revision={revision} onOperation={handleOperation} onToast={setToast} />}
          {view === 'users' && user.role === 'admin' && <UsersPage user={user} online={online} onToast={setToast} />}
          {view === 'account' && <AccountPage user={user} loggingOut={loggingOut} onLogout={() => void logout()} />}
        </>}
        <footer className="page-footer"><span><Brand compact /> <span>Porządek w magazynie. Spokój w pracy.</span></span><span><ShieldCheck size={14} /> Bezpieczne połączenie z magazynem</span></footer>
      </main>
    </div>
    <nav className="bottom-nav" aria-label="Nawigacja mobilna">{navigation.slice(0, 4).map((item) => <a href={`#${item.view}`} key={item.view} className={view === item.view ? 'bottom-active' : ''} aria-current={view === item.view ? 'page' : undefined}>{item.icon}<span>{item.view === 'history' ? 'Historia' : item.view === 'movements' ? 'Operacje' : item.label}</span></a>)}<button onClick={() => setMenuOpen(true)} aria-label="Więcej opcji"><Menu size={20} /><span>Więcej</span></button></nav>
    {operation && <Dialog title="Wynik operacji" onClose={() => setOperation(null)}><OperationResult operation={operation} checking={checking} onCheck={() => void checkOperation(operation.id)} /><div className="dialog-actions"><button className="button button-primary" onClick={() => setOperation(null)}>Zamknij</button></div></Dialog>}
    {toast && <div className="toast" role="status"><Info size={19} /><span>{toast}</span><button className="icon-button" onClick={() => setToast('')} aria-label="Zamknij komunikat"><X size={17} /></button></div>}
  </div>;
}

function Login({ online, message, onLogin }: { online: boolean; message: string; onLogin: (data: AuthResponse) => void }) {
  const [login, setLogin] = useState(''); const [password, setPassword] = useState(''); const [visible, setVisible] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [forgot, setForgot] = useState(false); const [resetSent, setResetSent] = useState(false);
  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try { await api.csrf(); if (forgot) { await api.request('/api/auth/password-reset/request', { method: 'POST', body: { login: login.trim() } }); setResetSent(true); } else onLogin(await api.request<AuthResponse>('/api/auth/login', { method: 'POST', body: { login: login.trim(), password } })); }
    catch (reason) { setError(errorMessage(reason)); }
    finally { setBusy(false); setPassword(''); }
  }
  return <div className="login-page"><aside className="login-story"><Brand /><div className="login-story-content"><span className="story-tag"><span /> DLA ZESPOŁÓW MEDYCZNYCH</span><h1>Twój magazyn.<br />Zawsze pod<br /><em>kontrolą.</em></h1><p>Preparaty, partie i terminy ważności.<br />Wszystko, czego potrzebujesz przed kolejnym wyjazdem.</p><div className="stock-illustration" aria-hidden="true"><div className="illustration-orbit orbit-one" /><div className="illustration-orbit orbit-two" /><div className="illustration-shelf"><span className="illustration-pill pill-a" /><span className="illustration-pill pill-b" /><span className="illustration-vial"><i /><b /></span><span className="illustration-box"><i>+</i><b /></span><span className="illustration-check"><Check size={19} /></span></div><div className="illustration-label"><ShieldCheck size={17} /><span>Każda partia ma znaczenie.</span></div></div></div><div className="login-story-bottom"><span className="story-line" /> EWIDENCJA · PORZĄDEK · BEZPIECZEŃSTWO</div></aside><main className="login-main"><div className="login-mobile-brand"><Brand /></div><div className="login-form-card"><div className="login-welcome-icon"><UserRound size={23} /></div><span className="eyebrow">DOBRZE CIĘ WIDZIEĆ</span><h2>{forgot ? 'Odzyskaj dostęp' : 'Zaloguj się do magazynu'}</h2><p className="login-intro">{forgot ? 'Podaj login swojego konta. Administrator pomoże Ci bezpiecznie ustawić nowe hasło.' : 'Twoje preparaty i historia operacji w jednym miejscu.'}</p>{message && <Alert kind="info">{message}</Alert>}{!online && <Alert kind="warning">Brak internetu. Logowanie wymaga połączenia z serwerem.</Alert>}{error && <Alert>{error}</Alert>}{resetSent ? <div className="reset-sent"><CheckCircle2 size={31} /><h3>Zgłoszenie zostało przyjęte</h3><p>Jeśli konto istnieje, dalsze kroki zależą od ustalonej w firmie procedury resetu. Skontaktuj się z administratorem.</p><button className="button button-primary" onClick={() => { setForgot(false); setResetSent(false); }}>Wróć do logowania</button></div> : <form onSubmit={(event) => void submit(event)}><Field label="Login"><label className="input-wrap"><UserRound size={18} /><input aria-label="Login" autoComplete="username" name="username" value={login} onChange={(e) => setLogin(e.target.value)} maxLength={254} placeholder="Twój login" required disabled={busy} autoFocus /></label></Field>{!forgot && <Field label="Hasło"><label className="input-wrap"><ShieldCheck size={18} /><input aria-label="Hasło" autoComplete="current-password" name="password" type={visible ? 'text' : 'password'} value={password} onChange={(e) => setPassword(e.target.value)} maxLength={128} placeholder="Wpisz hasło" required disabled={busy} /><button type="button" className="input-icon-button" onClick={() => setVisible(!visible)} aria-label={visible ? 'Ukryj hasło' : 'Pokaż hasło'}>{visible ? <EyeOff size={18} /> : <Eye size={18} />}</button></label></Field>}<div className="login-form-meta"><span><ShieldCheck size={14} /> Konto pracownika</span><button className="text-button" type="button" onClick={() => { setForgot(!forgot); setError(''); }}>{forgot ? 'Wróć do logowania' : 'Nie pamiętam hasła'}</button></div><button className="button button-primary button-block login-submit" disabled={busy || !online} type="submit">{busy ? <LoaderCircle size={18} className="spin" /> : <>{forgot ? 'Zgłoś prośbę o reset' : 'Zaloguj się'}<ArrowRight size={18} /></>}</button></form>}<div className="login-secure"><ShieldCheck size={16} /><span>Dostęp wyłącznie dla uprawnionych pracowników.<br />Konta przydziela administrator Twojego zespołu.</span></div></div><div className="login-main-footer"><span>© {new Date().getFullYear()} MEDAM</span><span>Magazyn medyczny</span></div></main></div>;
}

function PasswordReset({ token, online }: { token: string; online: boolean }) {
  const [password, setPassword] = useState(''); const [repeat, setRepeat] = useState(''); const [busy, setBusy] = useState(false); const [done, setDone] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setError(''); if (password !== repeat) { setError('Hasła muszą być jednakowe.'); return; } setBusy(true); try { await api.csrf(); await api.request('/api/auth/password-reset/confirm', { method: 'POST', body: { token, newPassword: password } }); setDone(true); setPassword(''); setRepeat(''); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } }
  return <main className="reset-page"><Brand /><section className="panel reset-panel"><ShieldCheck size={32} /><h1>{done ? 'Hasło zostało zmienione' : 'Ustaw nowe hasło'}</h1><p>{done ? 'Poprzednie sesje zostały unieważnione. Możesz zalogować się nowym hasłem.' : 'Użyj długiego, unikalnego hasła. Nie udostępniaj go innym osobom.'}</p>{error && <Alert>{error}</Alert>}{!token && !done && <Alert>Brakuje prawidłowego tokenu resetu. Poproś administratora o nowy link.</Alert>}{done ? <a href="/" className="button button-primary">Przejdź do logowania<ArrowRight size={18} /></a> : <form onSubmit={(e) => void submit(e)}><Field label="Nowe hasło"><input aria-label="Nowe hasło" type="password" value={password} onChange={(e) => setPassword(e.target.value)} minLength={12} maxLength={128} autoComplete="new-password" required disabled={busy} /></Field><Field label="Powtórz hasło"><input aria-label="Powtórz hasło" type="password" value={repeat} onChange={(e) => setRepeat(e.target.value)} minLength={12} maxLength={128} autoComplete="new-password" required disabled={busy} /></Field><button className="button button-primary button-block" disabled={busy || !online || !token}>{busy ? 'Zapisywanie…' : 'Zapisz nowe hasło'}</button></form>}</section></main>;
}

function PageHeading({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="page-heading"><div><h1>{title}</h1><p>{description}</p></div>{action && <div className="page-heading-action">{action}</div>}</div>; }

function StockPage({ user, online, revision, pendingId, onPending, onOperation, onToast }: { user: User; online: boolean; revision: number; pendingId: string | null; onPending: (id: string | null) => void; onOperation: (op: Operation) => void; onToast: (message: string) => void }) {
  const manager = isManager(user); const [warehouseId, setWarehouseId] = useState<number | null>(user.warehouse?.id ?? null); const [query, setQuery] = useState(''); const [debouncedQuery, setDebouncedQuery] = useState(''); const [filter, setFilter] = useState('all'); const [cursor, setCursor] = useState<string | null>(null); const [selected, setSelected] = useState<StockItem | null>(null); const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [policyOpen, setPolicyOpen] = useState(false);
  const warehouses = useResource<Page<Warehouse>>(() => manager ? api.request('/api/admin/warehouses') : Promise.resolve({ items: user.warehouse ? [user.warehouse] : [] }), [user.id, manager]);
  const effectiveWarehouseId = warehouseId ?? warehouses.data?.items[0]?.id ?? null;
  useEffect(() => { const timer = setTimeout(() => { setDebouncedQuery(query); setCursor(null); }, 250); return () => clearTimeout(timer); }, [query]);
  const endpoint = manager ? `/api/admin/warehouses/${effectiveWarehouseId}/stock` : '/api/my-stock';
  const resource = useResource<Page<StockItem>>(async () => { if (manager && effectiveWarehouseId === null) return { items: [] }; const params = new URLSearchParams({ q: debouncedQuery, filter, limit: '50' }); if (cursor) params.set('cursor', cursor); const result = await api.request<Page<StockItem>>(`${endpoint}?${params}`); setLastUpdated(new Date()); return result; }, [endpoint, debouncedQuery, filter, cursor, revision, effectiveWarehouseId]);
  const items = resource.data?.items ?? []; const products = new Set(items.map((item) => item.partId)).size; const low = items.filter((item) => item.warnings.some((warning) => /low|minimum|niski/i.test(warning))).length; const expiring = items.filter((item) => item.warnings.some((warning) => /expir|ważno|termin/i.test(warning))).length; const blocked = items.filter((item) => !item.eligibleForConsumption).length;
  const activeWarehouse = warehouses.data?.items.find((item) => item.id === effectiveWarehouseId) ?? user.warehouse;
  async function exportStock() { try { await api.download(`/api/admin/exports?kind=stock&warehouseId=${effectiveWarehouseId}`, `medam-magazyn-${activeWarehouse?.code ?? 'eksport'}.csv`); } catch (reason) { onToast(errorMessage(reason)); } }
  return <><PageHeading title={manager ? 'Magazyny' : 'Mój magazyn'} description={manager ? 'Przeglądaj zapasy i zarządzaj przygotowaniem zespołu.' : 'Wszystko, czego potrzebujesz do kolejnej wizyty.'} action={manager ? <button className="button button-primary" onClick={() => navigate('movements')}><Plus size={18} />Nowa operacja</button> : <button className="button button-secondary" onClick={() => navigate('reports')}><Flag size={17} />Zgłoś problem</button>} />
    <div className="warehouse-strip"><div className="warehouse-icon"><WarehouseIcon size={22} /></div><div><span className="eyebrow">{manager ? 'WYBRANY MAGAZYN' : 'TWÓJ PRZYDZIAŁ'}</span>{manager ? <label className="warehouse-select"><span className="sr-only">Wybierz magazyn</span><select value={effectiveWarehouseId ?? ''} onChange={(e) => { setWarehouseId(Number(e.target.value)); setCursor(null); }}>{warehouses.data?.items.map((warehouse) => <option key={warehouse.id} value={warehouse.id}>{warehouse.code} — {warehouse.name}</option>)}</select><ChevronDown size={17} /></label> : <strong>{activeWarehouse?.code ?? 'Brak przydziału'}<span> · {activeWarehouse?.name ?? 'Skontaktuj się z administratorem'}</span></strong>}</div><div className="warehouse-strip-right"><ShieldCheck size={17} /><span>{manager ? 'Widok operacyjny' : 'Dostęp do własnego magazynu'}</span></div></div>
    {warehouses.error && <Alert>{warehouses.error}</Alert>}
    <div className="summary-grid"><Summary icon={<FlaskConical size={21} />} label="Preparaty w wynikach" value={products} note={`${items.length} ${items.length === 1 ? 'partia' : 'partii'} na tej stronie`} /><Summary icon={<ArrowDownToLine size={21} />} label="Niski stan" value={low} note="Partie wymagające uwagi" tone={low ? 'amber' : undefined} /><Summary icon={<Clock3 size={21} />} label="Termin ważności" value={expiring} note="Ostrzeżenia w wynikach" tone={expiring ? 'amber' : undefined} /><Summary icon={<ShieldCheck size={21} />} label="Zablokowane partie" value={blocked} note="Niedopuszczone do zużycia" /></div>
    <section className="panel inventory-panel"><div className="panel-heading"><div><h2>Preparaty i partie <span className="count-badge">{items.length}</span></h2><p>Wybierz partię, aby zarejestrować rzeczywiste zużycie.</p></div><div className="panel-heading-actions">{manager && <><button className="text-button" onClick={() => setPolicyOpen(true)} disabled={effectiveWarehouseId === null}><SlidersHorizontal size={17} />Minima i jednostki</button><button className="icon-button" title="Eksportuj wybrany magazyn" aria-label="Eksportuj wybrany magazyn" onClick={() => void exportStock()} disabled={effectiveWarehouseId === null}><Download size={18} /></button></>}<button className="icon-button" title="Odśwież stany" aria-label="Odśwież stany" disabled={resource.loading || !online} onClick={resource.reload}><RefreshCw size={18} className={resource.loading ? 'spin' : ''} /></button></div></div>
      <div className="inventory-tools"><label className="search-input"><Search size={18} /><input type="search" aria-label="Szukaj preparatu lub partii" placeholder="Szukaj preparatu lub numeru LOT…" value={query} maxLength={80} onChange={(e) => setQuery(e.target.value)} />{query && <button className="input-icon-button" onClick={() => setQuery('')} aria-label="Wyczyść wyszukiwanie"><X size={16} /></button>}</label><div className="filter-chips" aria-label="Filtr zapasów">{[{ id: 'all', label: 'Wszystkie' }, { id: 'low', label: 'Niski stan' }, { id: 'expiring', label: 'Krótki termin' }, { id: 'blocked', label: 'Zablokowane' }].map((item) => <button key={item.id} onClick={() => { setFilter(item.id); setCursor(null); }} className={`filter-chip ${filter === item.id ? 'filter-active' : ''}`} aria-pressed={filter === item.id}>{item.label}</button>)}</div></div>
      {resource.error ? <div className="panel-error"><Alert action={<button className="text-button" onClick={resource.reload}>Spróbuj odświeżyć<RefreshCw size={15} /></button>}>{resource.error}</Alert></div> : resource.loading ? <Spinner label="Pobieranie aktualnych stanów…" /> : !items.length ? <Empty title={query || filter !== 'all' ? 'Nie znaleziono pasujących partii' : 'Magazyn czeka na pierwsze preparaty'}>{query || filter !== 'all' ? 'Zmień wyszukiwanie lub wybierz inny filtr.' : manager ? 'Zarejestruj przyjęcie dostawy, aby dodać zapasy do magazynu.' : 'Po przyjęciu lub przesunięciu preparatów zobaczysz je tutaj.'}</Empty> : <div className="stock-table"><div className="stock-table-head"><span>PREPARAT / PARTIA</span><span>ILOŚĆ</span><span>WAŻNOŚĆ</span><span>STATUS</span><span /></div>{items.map((item) => <StockRow key={item.id} item={item} disabled={!online || !!pendingId} onSelect={() => setSelected(item)} />)}</div>}
      <div className="table-footer"><span><span className="status-dot" />{lastUpdated ? `Aktualizacja ${new Intl.DateTimeFormat('pl-PL', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Warsaw' }).format(lastUpdated)}` : 'Dane z systemu magazynowego'}</span><span className="table-footer-note">FEFO · Najkrótszy termin w pierwszej kolejności</span><div className="pagination">{cursor && <button className="text-button" onClick={() => setCursor(null)}><ArrowLeft size={15} />Początek</button>}{resource.data?.nextCursor && <button className="text-button" onClick={() => setCursor(resource.data?.nextCursor ?? null)}>Dalej<ChevronRight size={15} /></button>}</div></div>
    </section><div className="help-strip"><Info size={18} /><p><strong>Każde zużycie zapisuj po wykonaniu usługi.</strong> Zgłoszenie problemu nie zmienia automatycznie stanu magazynowego.</p></div>
    {selected && <ConsumeDialog item={selected} user={user} online={online} onClose={() => setSelected(null)} onPending={onPending} onOperation={(result) => { setSelected(null); onOperation(result); }} />}
    {manager && policyOpen && <StockPolicyDialog warehouses={warehouses.data?.items ?? []} initialWarehouseId={effectiveWarehouseId} online={online} locked={!!pendingId} onClose={() => setPolicyOpen(false)} onSaved={resource.reload} />}
  </>;
}

type StockPolicy = { warehouseId: number; partId: number; minimum: string; quantum: string };
function StockPolicyDialog({ warehouses, initialWarehouseId, online, locked, onClose, onSaved }: { warehouses: Warehouse[]; initialWarehouseId: number | null; online: boolean; locked: boolean; onClose: () => void; onSaved: () => void }) {
  const [warehouseId, setWarehouseId] = useState(String(initialWarehouseId ?? '')); const [partId, setPartId] = useState(''); const [cursor, setCursor] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  const parts = useResource<Page<Part>>(() => api.request(`/api/admin/parts?${new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) })}`), [cursor]);
  const part = parts.data?.items.find(item => String(item.id) === partId);
  return <Dialog title="Minima i jednostki" subtitle="Ustaw próg niskiego stanu i dopuszczalny krok ilości dla preparatu w wybranym magazynie." onClose={() => { if (!busy) onClose(); }}>
    {locked && <Alert kind="warning">Sprawdź lub uzgodnij poprzednią operację przed zmianą ustawień.</Alert>}
    <Field label="Magazyn"><select aria-label="Magazyn ustawień" value={warehouseId} onChange={e => setWarehouseId(e.target.value)} disabled={busy} required><option value="">Wybierz magazyn</option>{warehouses.map(item => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></Field>
    <Field label="Preparat"><select aria-label="Preparat ustawień" value={partId} onChange={e => setPartId(e.target.value)} disabled={busy || parts.loading || !!parts.error} required><option value="">Wybierz preparat</option>{parts.data?.items.map(item => <option key={item.id} value={item.id}>{item.name} ({item.unit})</option>)}</select></Field>
    {parts.loading ? <Spinner label="Pobieranie preparatów…" /> : parts.error ? <Alert action={<button className="text-button" onClick={parts.reload}>Spróbuj ponownie</button>}>{parts.error}</Alert> : !parts.data?.items.length && <Alert kind="info">Brak preparatów do konfiguracji.</Alert>}
    {!busy && <PagePagination cursor={cursor} next={parts.data?.nextCursor} onChange={value => { setCursor(value); setPartId(''); }} />}
    {warehouseId && part && !parts.loading && !parts.error && <StockPolicyForm key={`${warehouseId}:${partId}`} endpoint={`/api/admin/warehouses/${warehouseId}/policies/${partId}`} unit={part.unit} online={online} locked={locked} onBusy={setBusy} onSaved={onSaved} />}
    <div className="dialog-actions"><button className="button button-secondary" onClick={onClose} disabled={busy}>Zamknij</button></div>
  </Dialog>;
}

function StockPolicyForm({ endpoint, unit, online, locked, onBusy, onSaved }: { endpoint: string; unit: string; online: boolean; locked: boolean; onBusy: (value: boolean) => void; onSaved: () => void }) {
  const resource = useResource<StockPolicy>(() => api.request(endpoint), []);
  const [minimum, setMinimum] = useState<string | null>(null); const [quantum, setQuantum] = useState<string | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [saved, setSaved] = useState(false); const busyRef = useRef(false);
  async function submit(event: FormEvent) {
    event.preventDefault(); if (busyRef.current || !resource.data || !online || locked) return;
    const values = { minimum: minimum ?? resource.data.minimum, quantum: quantum ?? resource.data.quantum };
    setError(''); setSaved(false);
    if (![values.minimum, values.quantum].every(value => /^(0|[1-9]\d{0,9})(\.\d{1,5})?$/.test(value)) || Number(values.quantum) <= 0) { setError('Minimum musi być nieujemne, a krok ilości dodatni. Użyj kropki i maksymalnie 5 miejsc po przecinku.'); return; }
    busyRef.current = true; setBusy(true); onBusy(true);
    try { const result = await api.request<StockPolicy>(endpoint, { method: 'PUT', body: values }); setMinimum(result.minimum); setQuantum(result.quantum); setSaved(true); onSaved(); }
    catch (reason) { setError(errorMessage(reason)); }
    finally { busyRef.current = false; setBusy(false); onBusy(false); }
  }
  if (resource.loading) return <Spinner label="Pobieranie ustawień…" />;
  if (resource.error || !resource.data) return <Alert action={<button className="text-button" onClick={resource.reload}>Spróbuj ponownie</button>}>{resource.error || 'Nie udało się pobrać ustawień.'}</Alert>;
  return <form onSubmit={event => void submit(event)}>{error && <Alert>{error}</Alert>}{saved && <Alert kind="success">Ustawienia zostały zapisane.</Alert>}<fieldset disabled={busy || !online || locked}><div className="form-columns"><Field label={`Minimum (${unit})`} hint="0 wyłącza ostrzeżenie o niskim stanie."><input aria-label="Minimum" inputMode="decimal" value={minimum ?? resource.data.minimum} onChange={e => { setMinimum(e.target.value); setSaved(false); }} maxLength={16} required /></Field><Field label={`Krok ilości (${unit})`} hint="Ilość operacji musi być wielokrotnością tego kroku, np. 1 lub 0.5."><input aria-label="Krok ilości" inputMode="decimal" value={quantum ?? resource.data.quantum} onChange={e => { setQuantum(e.target.value); setSaved(false); }} maxLength={16} required /></Field></div><button type="submit" className="button button-primary button-block">{busy ? <LoaderCircle size={17} className="spin" /> : <Check size={17} />}{busy ? 'Zapisywanie…' : 'Zapisz ustawienia'}</button></fieldset></form>;
}

function Summary({ icon, label, value, note, tone }: { icon: ReactNode; label: string; value: number; note: string; tone?: string | undefined }) { return <div className={`summary-card ${tone ? `summary-${tone}` : ''}`}><div className="summary-card-top"><span>{label}</span><div className="summary-icon">{icon}</div></div><strong className="summary-value">{value.toString().padStart(2, '0')}</strong><span className="summary-note">{note}</span></div>; }

function StockRow({ item, disabled, onSelect }: { item: StockItem; disabled: boolean; onSelect: () => void }) {
  const low = item.warnings.some((value) => /low|minimum|niski/i.test(value)); const expiring = item.warnings.some((value) => /expir|ważno|termin/i.test(value));
  return <article className={`stock-row ${!item.eligibleForConsumption ? 'stock-row-blocked' : ''}`}><div className="stock-name"><div className="medicine-icon"><FlaskConical size={20} strokeWidth={1.7} /></div><div><h3>{item.name}</h3><span className="lot-label">LOT <strong>{item.lot || 'Brak numeru'}</strong></span></div></div><div className="stock-quantity"><strong>{quantityLabel(item.quantity)} <small>{item.unit}</small></strong><span>Minimum: {quantityLabel(item.minimum)} {item.unit}</span></div><div className={`stock-exp ${expiring ? 'exp-warning' : ''}`}><span><Clock3 size={14} />{dateLabel(item.exp)}</span>{expiring && <small>Sprawdź termin ważności</small>}</div><div className="stock-status">{!item.eligibleForConsumption ? <Badge tone="danger">Niedostępna</Badge> : low ? <Badge tone="warning">Niski stan</Badge> : expiring ? <Badge tone="warning">Krótki termin</Badge> : <Badge tone="success">Dostępna</Badge>}</div><div className="stock-action"><button className="stock-use-button" onClick={onSelect} disabled={disabled || !item.eligibleForConsumption} aria-label={`Zarejestruj zużycie ${item.name}, LOT ${item.lot ?? 'brak'}`}><span>Zarejestruj zużycie</span><ArrowUpRight size={17} /></button></div></article>;
}

function ConsumeDialog({ item, user, online, onClose, onPending, onOperation }: { item: StockItem; user: User; online: boolean; onClose: () => void; onPending: (id: string | null) => void; onOperation: (op: Operation) => void }) {
  const [quantity, setQuantity] = useState('1'); const [confirm, setConfirm] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [uncertainId, setUncertainId] = useState<string | null>(null);
  function next(event: FormEvent) { event.preventDefault(); if (!/^(0|[1-9]\d{0,9})(\.\d{1,5})?$/.test(quantity) || Number(quantity) <= 0) { setError('Podaj dodatnią ilość. Użyj kropki jako separatora części dziesiętnej.'); return; } if (Number(quantity) > Number(item.availableQuantity)) { setError('Wprowadzona ilość przekracza dostępny stan.'); return; } setError(''); setConfirm(true); }
  async function submit() { if (busy) return; const id = crypto.randomUUID(); onPending(id); setBusy(true); setError(''); try { const result = await api.request<Operation>(isManager(user) ? '/api/admin/consumptions' : '/api/consumptions', { method: 'POST', idempotencyKey: id, body: { stockItemId: item.id, quantity } }); onOperation(result); } catch (reason) { setError(errorMessage(reason)); if (reason instanceof ApiError && reason.status >= 400 && reason.status < 500 && !reason.operationId) { onPending(null); setConfirm(false); } else { setUncertainId(id); try { onOperation(await api.request<Operation>(`/api/operations/${id}`)); } catch { /* A missing status is not evidence that the original request cannot still execute. */ } } } finally { setBusy(false); } }
  return <Dialog title={confirm ? 'Potwierdź zużycie' : 'Rejestracja zużycia'} subtitle="Zapis dotyczy jednej, wybranej partii preparatu." onClose={() => { if (!busy) onClose(); }}><div className="selected-medicine"><div className="medicine-icon"><FlaskConical size={24} /></div><div><h3>{item.name}</h3><span>LOT {item.lot} · EXP {dateLabel(item.exp)}</span></div><Badge tone="teal">{quantityLabel(item.availableQuantity)} {item.unit}</Badge></div>{error && <Alert>{error}</Alert>}{uncertainId ? <div className="uncertain-block"><Alert kind="warning"><strong>Nie potwierdzono wyniku.</strong><p>Nie rejestruj zużycia ponownie. Sprawdź status operacji po powrocie połączenia.</p><code>{uncertainId}</code></Alert><button className="button button-primary" onClick={async () => { setBusy(true); try { onOperation(await api.request<Operation>(`/api/operations/${uncertainId}`)); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } }} disabled={busy || !online}>{busy ? 'Sprawdzanie…' : 'Sprawdź status operacji'}</button></div> : confirm ? <><div className="confirmation-summary"><div><span>Rejestrowane zużycie</span><strong>{quantityLabel(quantity)} <small>{item.unit}</small></strong></div><div><span>Numer partii</span><strong className="summary-lot">{item.lot}</strong></div></div><div className="form-note"><ShieldCheck size={17} /><p>Po potwierdzeniu serwer ponownie sprawdzi partię i dostępny stan. Wynik zobaczysz po weryfikacji zapisu.</p></div><div className="dialog-actions"><button className="button button-secondary" onClick={() => setConfirm(false)} disabled={busy}>Wstecz</button><button className="button button-primary" onClick={() => void submit()} disabled={busy || !online}>{busy ? <><LoaderCircle className="spin" size={17} />Zapisywanie…</> : <><Check size={17} />Potwierdź zużycie</>}</button></div></> : <form onSubmit={next}><Field label={`Ilość zużyta (${item.unit})`} hint={`Dostępne: ${quantityLabel(item.availableQuantity)} ${item.unit}. Jednostka jest przypisana do preparatu.`}><input aria-label="Ilość zużyta" autoFocus inputMode="decimal" value={quantity} onChange={(e) => setQuantity(e.target.value)} maxLength={16} required /></Field><div className="form-note"><Info size={17} /><p>Wpisz rzeczywiście zużytą ilość. W tej aplikacji nie zapisujemy danych pacjenta.</p></div><div className="dialog-actions"><button type="button" className="button button-secondary" onClick={onClose}>Anuluj</button><button className="button button-primary" disabled={!online}>Dalej<ArrowRight size={17} /></button></div></form>}</Dialog>;
}

const actionLabels: Record<string, string> = {
  'consumption': 'Zużycie preparatu', 'consume': 'Zużycie preparatu', 'stock.consume': 'Zużycie preparatu',
  'receipt': 'Przyjęcie dostawy', 'stock.receipt': 'Przyjęcie dostawy',
  'transfer': 'Przesunięcie zapasów', 'stock.transfer': 'Przesunięcie zapasów',
  'adjustment': 'Korekta magazynowa', 'stock.adjust': 'Korekta magazynowa',
  'problem.created': 'Zgłoszenie problemu', 'problem_report.created': 'Zgłoszenie problemu',
  'auth.login': 'Logowanie', 'auth.logout': 'Wylogowanie', 'user.created': 'Utworzenie konta',
};
function actionLabel(value: string) { return actionLabels[value] ?? (/consum/i.test(value) ? 'Zużycie preparatu' : /transfer/i.test(value) ? 'Przesunięcie zapasów' : /receipt/i.test(value) ? 'Przyjęcie dostawy' : /problem/i.test(value) ? 'Zgłoszenie problemu' : value.replaceAll('_', ' ').replaceAll('.', ' · ')); }
function detailText(details: Record<string, unknown>, key: string): string { const value = details[key]; return typeof value === 'string' || typeof value === 'number' ? String(value) : ''; }
function PagePagination({ cursor, next, onChange }: { cursor: string | null; next?: string | null | undefined; onChange: (value: string | null) => void }) {
  if (!cursor && !next) return null;
  return <div className="list-pagination">{cursor ? <button className="button button-secondary" onClick={() => onChange(null)}><ArrowLeft size={16} />Początek</button> : <span />}{next && <button className="button button-secondary" onClick={() => onChange(next)}>Kolejne wpisy<ArrowRight size={16} /></button>}</div>;
}

function HistoryPage({ user, revision, onOperation, onToast }: { user: User; revision: number; onOperation: (id: string) => void; onToast: (message: string) => void }) {
  const [cursor, setCursor] = useState<string | null>(null);
  const resource = useResource<Page<HistoryItem>>(() => api.request(`${isManager(user) ? '/api/admin/audit' : '/api/my-history'}?${new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) })}`), [user.id, revision, cursor]);
  async function exportHistory() { try { await api.download('/api/admin/exports?kind=operations', 'medam-historia.csv'); } catch (error) { onToast(errorMessage(error)); } }
  return <><PageHeading title="Historia operacji" description={isManager(user) ? 'Ślad operacji magazynowych i działań zespołu.' : 'Twoje operacje, ich wyniki i czas zapisu.'} action={isManager(user) ? <button className="button button-secondary" onClick={() => void exportHistory()}><Download size={17} />Eksport CSV</button> : undefined} />
    <section className="panel"><div className="panel-heading"><div><h2>Ostatnie zdarzenia</h2><p>Potwierdzony wynik jest widoczny przy każdej operacji.</p></div><button className="icon-button" aria-label="Odśwież historię" disabled={resource.loading} onClick={resource.reload}><RefreshCw size={18} /></button></div>
      {resource.error ? <div className="panel-padding"><Alert>{resource.error}</Alert></div> : resource.loading ? <Spinner label="Pobieranie historii…" /> : !resource.data?.items.length ? <Empty title="Historia jest jeszcze pusta">Pierwsze działania pojawią się tutaj po zapisaniu operacji.</Empty> : <div className="history-list">{resource.data.items.map((item) => <article className="history-row" key={item.id}><div className="history-icon">{/consum|remove/i.test(item.action) ? <ArrowUpRight size={20} /> : /transfer/i.test(item.action) ? <ArrowLeftRight size={20} /> : /problem/i.test(item.action) ? <Flag size={20} /> : <Activity size={20} />}</div><div className="history-copy"><h3>{actionLabel(item.action)}</h3><p>{detailText(item.details, 'name') || detailText(item.details, 'reason') || 'Zdarzenie w ewidencji magazynu'}{detailText(item.details, 'quantity') && <span> · Ilość: {quantityLabel(detailText(item.details, 'quantity'))}</span>}</p><time>{timestampLabel(item.createdAt)}</time></div><div className="history-result"><OperationBadge state={item.outcome} />{item.operationId && <button className="text-button" onClick={() => onOperation(item.operationId!)}>Szczegóły<ChevronRight size={15} /></button>}</div></article>)}</div>}
      <PagePagination cursor={cursor} next={resource.data?.nextCursor} onChange={setCursor} />
    </section></>;
}

function ReportsPage({ user, online, revision, onToast }: { user: User; online: boolean; revision: number; onToast: (message: string) => void }) {
  const [open, setOpen] = useState(false); const [localRevision, setLocalRevision] = useState(0); const [cursor, setCursor] = useState<string | null>(null);
  const resource = useResource<Page<ProblemReport>>(() => api.request(`/api/problem-reports?${new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) })}`), [user.id, revision, localRevision, cursor]);
  return <><PageHeading title="Zgłoszenia" description={isManager(user) ? 'Problemy zgłoszone przez ratowników. Rozpatrzenie nie zastępuje operacji magazynowej.' : 'Zgłoś uszkodzenie, termin ważności lub rozbieżność.'} action={!isManager(user) ? <button className="button button-primary" disabled={!online} onClick={() => setOpen(true)}><Plus size={18} />Nowe zgłoszenie</button> : undefined} /><div className="help-strip"><Info size={18} /><p>Zgłoszenie <strong>nie zmienia stanu magazynu.</strong> Do czasu wyjaśnienia odłóż preparat zgodnie z procedurą zespołu.</p></div>
    <section className="panel"><div className="panel-heading"><div><h2>{isManager(user) ? 'Zgłoszenia zespołu' : 'Moje zgłoszenia'}</h2><p>Bez danych pacjentów i szczegółów dokumentacji medycznej.</p></div><button className="icon-button" onClick={resource.reload} disabled={resource.loading} aria-label="Odśwież zgłoszenia"><RefreshCw size={18} /></button></div>
      {resource.error ? <div className="panel-padding"><Alert>{resource.error}</Alert></div> : resource.loading ? <Spinner label="Pobieranie zgłoszeń…" /> : !resource.data?.items.length ? <Empty title="Nie ma jeszcze zgłoszeń">Problemy wymagające sprawdzenia będą widoczne w tym miejscu.</Empty> : <div className="reports-list">{resource.data.items.map((item) => <article key={item.id} className="report-card"><div className="report-card-heading"><span className="report-category"><Flag size={17} />{categoryLabels[item.category] ?? 'Zgłoszenie'}</span><Badge tone={item.status === 'resolved' || item.status === 'closed' ? 'success' : 'warning'}>{item.status === 'resolved' || item.status === 'closed' ? 'Rozpatrzone' : 'Do rozpatrzenia'}</Badge></div><p>{item.description}</p><div className="report-card-footer"><time>{timestampLabel(item.createdAt)}</time>{item.stockItemId && <span>Pozycja #{item.stockItemId}</span>}<code>{item.id.slice(0, 8)}</code></div></article>)}</div>}
      <PagePagination cursor={cursor} next={resource.data?.nextCursor} onChange={setCursor} />
    </section>{open && <ProblemDialog online={online} onClose={() => setOpen(false)} onSaved={() => { setOpen(false); setLocalRevision(value => value + 1); onToast('Zgłoszenie zostało zapisane. Stan magazynu pozostał bez zmian.'); }} />}</>;
}

function ProblemDialog({ online, onClose, onSaved }: { online: boolean; onClose: () => void; onSaved: () => void }) {
  const [category, setCategory] = useState<ProblemCategory>('damage'); const [stockId, setStockId] = useState(''); const [description, setDescription] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [uncertain, setUncertain] = useState(false); const key = useRef(crypto.randomUUID());
  const stock = useResource<Page<StockItem>>(() => api.request('/api/my-stock?limit=50'), []);
  async function submit(event: FormEvent) { event.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await api.request('/api/problem-reports', { method: 'POST', idempotencyKey: key.current, body: { category, description: description.trim(), ...(stockId ? { stockItemId: Number(stockId) } : {}) } }); onSaved(); } catch (reason) { setError(errorMessage(reason)); if (!(reason instanceof ApiError) || !reason.status || reason.status >= 500) setUncertain(true); } finally { setBusy(false); } }
  return <Dialog title="Zgłoś problem" subtitle="Opisz wyłącznie problem z preparatem lub stanem magazynowym." onClose={() => { if (!busy) onClose(); }}><form onSubmit={(event) => void submit(event)}>{error && <Alert>{error}</Alert>}{uncertain && <Alert kind="warning">Nie odebrano potwierdzenia. Ponowne wysłanie użyje tego samego identyfikatora zgłoszenia.</Alert>}<Field label="Rodzaj problemu"><select aria-label="Rodzaj problemu" value={category} onChange={e => setCategory(e.target.value as ProblemCategory)} disabled={busy || uncertain}>{Object.entries(categoryLabels).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></Field><Field label="Partia preparatu (opcjonalnie)"><select aria-label="Partia preparatu" value={stockId} onChange={e => setStockId(e.target.value)} disabled={busy || uncertain}><option value="">Zgłoszenie ogólne</option>{stock.data?.items.map(item => <option key={item.id} value={item.id}>{item.name} — LOT {item.lot ?? 'brak'}</option>)}</select></Field><Field label="Opis problemu" hint="Nie wpisuj imienia, nazwiska ani innych danych pacjenta."><textarea aria-label="Opis problemu" value={description} onChange={e => setDescription(e.target.value)} minLength={5} maxLength={1000} rows={4} required disabled={busy || uncertain} placeholder="Co wymaga sprawdzenia?" /></Field><div className="form-note"><Info size={17} /><p>Zgłoszenie nie powoduje zwiększenia ani zmniejszenia zapasu.</p></div><div className="dialog-actions"><button type="button" className="button button-secondary" onClick={onClose} disabled={busy}>Zamknij</button><button type="submit" className="button button-primary" disabled={busy || !online}>{busy ? <LoaderCircle className="spin" size={17} /> : <Flag size={17} />}{uncertain ? 'Ponów to samo zgłoszenie' : 'Wyślij zgłoszenie'}</button></div></form></Dialog>;
}

type MovementKind = 'receipt' | 'transfer' | 'adjustment';
function MovementsPage({ online, pendingId, onPending, onOperation }: { online: boolean; pendingId: string | null; onPending: (id: string | null) => void; onOperation: (op: Operation) => void }) {
  const [kind, setKind] = useState<MovementKind>('receipt'); const [source, setSource] = useState(''); const [destination, setDestination] = useState(''); const [stockId, setStockId] = useState(''); const [partId, setPartId] = useState(''); const [quantity, setQuantity] = useState('1'); const [lot, setLot] = useState(''); const [exp, setExp] = useState(''); const [direction, setDirection] = useState('decrease'); const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const busyRef = useRef(false);
  const warehouses = useResource<Page<Warehouse>>(() => api.request('/api/admin/warehouses'), []);
  const parts = useResource<Page<Part>>(() => api.request('/api/admin/parts?limit=50'), []);
  const selectedSource = source || String(warehouses.data?.items[0]?.id ?? '');
  const stock = useResource<Page<StockItem>>(() => selectedSource ? api.request(`/api/admin/warehouses/${selectedSource}/stock?limit=50`) : Promise.resolve({ items: [] }), [selectedSource, kind]);
  const selectedItem = stock.data?.items.find(item => String(item.id) === stockId);
  function changeKind(value: MovementKind) { setKind(value); setStockId(''); setError(''); }
  async function submit(event: FormEvent) {
    event.preventDefault(); if (busyRef.current || pendingId) return; setError('');
    if (kind === 'transfer' && destination === selectedSource) { setError('Wybierz inny magazyn docelowy.'); return; }
    const body = kind === 'receipt' ? { partId: Number(partId), warehouseId: Number(selectedSource), quantity, lot: lot.trim(), exp } : kind === 'transfer' ? { stockItemId: Number(stockId), destinationWarehouseId: Number(destination), quantity } : { stockItemId: Number(stockId), quantity, direction, reason: reason.trim() };
    const endpoint = kind === 'receipt' ? '/api/admin/receipts' : kind === 'transfer' ? '/api/admin/warehouse-transfers' : '/api/admin/adjustments';
    const id = crypto.randomUUID(); busyRef.current = true; setBusy(true); onPending(id);
    try { onOperation(await api.request<Operation>(endpoint, { method: 'POST', idempotencyKey: id, body })); setQuantity('1'); setLot(''); setExp(''); setReason(''); stock.reload(); }
    catch (failure) { setError(errorMessage(failure)); if (failure instanceof ApiError && failure.status >= 400 && failure.status < 500 && !failure.operationId) onPending(null); else { try { onOperation(await api.request<Operation>(`/api/operations/${id}`)); } catch { setError('Nie potwierdzono wyniku operacji. Nie wysyłaj jej ponownie; sprawdź status u góry ekranu.'); } } }
    finally { busyRef.current = false; setBusy(false); }
  }
  return <><PageHeading title="Operacje magazynowe" description="Przyjmuj dostawy, przesuwaj partie i rozliczaj korekty." /><div className="movement-layout"><section className="panel movement-panel"><div className="operation-tabs" aria-label="Rodzaj operacji">{[{ id: 'receipt' as const, label: 'Przyjęcie', icon: <ArrowDownLeft size={18} /> }, { id: 'transfer' as const, label: 'Przesunięcie', icon: <ArrowLeftRight size={18} /> }, { id: 'adjustment' as const, label: 'Korekta', icon: <SlidersHorizontal size={18} /> }].map(tab => <button key={tab.id} className={kind === tab.id ? 'operation-tab-active' : ''} onClick={() => changeKind(tab.id)} disabled={busy}>{tab.icon}{tab.label}</button>)}</div><form className="panel-padding" onSubmit={(event) => void submit(event)}>{error && <Alert>{error}</Alert>}{warehouses.error && <Alert>{warehouses.error}</Alert>}<h2>{kind === 'receipt' ? 'Przyjmij nową partię' : kind === 'transfer' ? 'Przesuń zapasy' : 'Rozlicz korektę'}</h2><p className="section-description">{kind === 'receipt' ? 'Dane LOT i EXP przepisz z opakowania dostarczonego preparatu.' : kind === 'transfer' ? 'Przesunięcie zachowuje dane partii i termin ważności.' : 'Każda korekta wymaga konkretnego powodu i pozostaje w audycie.'}</p><fieldset disabled={busy || !!pendingId || !online}><Field label={kind === 'receipt' ? 'Magazyn przyjmujący' : 'Magazyn źródłowy'}><select aria-label={kind === 'receipt' ? 'Magazyn przyjmujący' : 'Magazyn źródłowy'} value={selectedSource} onChange={e => { setSource(e.target.value); setStockId(''); }} required><option value="">Wybierz magazyn</option>{warehouses.data?.items.map(item => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></Field>{kind === 'receipt' ? <><Field label="Preparat"><select aria-label="Preparat" value={partId} onChange={e => setPartId(e.target.value)} required><option value="">Wybierz preparat</option>{parts.data?.items.map(item => <option key={item.id} value={item.id}>{item.name} ({item.unit})</option>)}</select></Field>{parts.error && <Alert>{parts.error}</Alert>}<div className="form-columns"><Field label="Numer LOT"><input aria-label="Numer LOT" value={lot} onChange={e => setLot(e.target.value)} maxLength={100} required /></Field><Field label="Data EXP"><input aria-label="Data EXP" type="date" value={exp} onChange={e => setExp(e.target.value)} required /></Field></div></> : <><Field label="Partia źródłowa"><select aria-label="Partia źródłowa" value={stockId} onChange={e => setStockId(e.target.value)} required><option value="">Wybierz pozycję</option>{stock.data?.items.map(item => <option key={item.id} value={item.id}>{item.name} — LOT {item.lot ?? 'brak'} — {item.quantity} {item.unit}</option>)}</select></Field>{stock.error && <Alert>{stock.error}</Alert>}{selectedItem && <div className="selected-part-note"><Package size={16} />LOT {selectedItem.lot ?? 'brak'} · EXP {dateLabel(selectedItem.exp)} · {selectedItem.quantity} {selectedItem.unit}</div>}</>}{kind === 'transfer' && <Field label="Magazyn docelowy"><select aria-label="Magazyn docelowy" value={destination} onChange={e => setDestination(e.target.value)} required><option value="">Wybierz magazyn docelowy</option>{warehouses.data?.items.filter(item => String(item.id) !== selectedSource).map(item => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></Field>}{kind === 'adjustment' && <Field label="Kierunek korekty"><select aria-label="Kierunek korekty" value={direction} onChange={e => setDirection(e.target.value)}><option value="decrease">Zmniejszenie — strata, uszkodzenie, rozbieżność</option><option value="increase">Zwiększenie — zatwierdzony zwrot lub korekta</option></select></Field>}<Field label="Ilość" hint="Jednostka jest przypisana do preparatu. Użyj kropki dla części dziesiętnej."><input aria-label="Ilość" inputMode="decimal" pattern="(?:0|[1-9][0-9]{0,9})(?:\.[0-9]{1,5})?" value={quantity} onChange={e => setQuantity(e.target.value)} maxLength={16} required /></Field>{kind === 'adjustment' && <Field label="Powód korekty"><textarea aria-label="Powód korekty" value={reason} onChange={e => setReason(e.target.value)} minLength={5} maxLength={500} rows={3} required /></Field>}<div className="form-note"><ShieldCheck size={17} /><p>Sprawdź dane przed zapisem. Potwierdzenie pojawi się po zweryfikowaniu wyniku w magazynie.</p></div><button className="button button-primary button-block" type="submit">{busy ? <LoaderCircle size={17} className="spin" /> : <Check size={17} />}{busy ? 'Weryfikowanie operacji…' : kind === 'receipt' ? 'Zapisz przyjęcie' : kind === 'transfer' ? 'Zapisz przesunięcie' : 'Zapisz korektę'}</button></fieldset></form></section><aside className="movement-help"><div className="panel help-panel"><div className="help-panel-icon"><ShieldCheck size={23} /></div><h3>Jedna operacja.<br />Pełny ślad.</h3><p>Każdy zapis ma unikalny identyfikator i zostaje powiązany z Twoim kontem.</p><ul><li>Sprawdź preparat i wybraną partię.</li><li>Porównaj LOT i EXP z opakowaniem.</li><li>Po utracie połączenia sprawdź status, zamiast ponawiać zapis.</li></ul></div><div className="help-strip"><Info size={18} /><p>Korekta straty służy ewidencji. Nie dopuszcza uszkodzonej ani przeterminowanej partii do użycia.</p></div></aside></div></>;
}

function ReviewPage({ online, revision, onOperation, onToast }: { online: boolean; revision: number; onOperation: (op: Operation) => void; onToast: (message: string) => void }) {
  const [selected, setSelected] = useState<Operation | null>(null); const [localRevision, setLocalRevision] = useState(0);
  const resource = useResource<Page<Operation>>(() => api.request('/api/admin/operations?state=review&limit=50'), [revision, localRevision]);
  return <><PageHeading title="Uzgadnianie operacji" description="Rozstrzygaj niepewne wyniki na podstawie dowodów z historii magazynu." /><Alert kind="info">Niepewny wynik zatrzymuje kolejne zapisy magazynowe. Sam upływ czasu ani brak wpisu nie potwierdzają, że operacja nie została wykonana.</Alert><section className="panel"><div className="panel-heading"><div><h2>Wymagają sprawdzenia</h2><p>Rozstrzygnięcie jest zapisywane z uzasadnieniem i kontem administratora.</p></div><button className="icon-button" aria-label="Odśwież operacje" onClick={resource.reload} disabled={resource.loading}><RefreshCw size={18} /></button></div>{resource.error ? <div className="panel-padding"><Alert>{resource.error}</Alert></div> : resource.loading ? <Spinner label="Pobieranie operacji…" /> : !resource.data?.items.length ? <Empty title="Wszystkie wyniki są rozstrzygnięte">Nie ma operacji wymagających uzgodnienia.</Empty> : <div className="review-list">{resource.data.items.map(item => <article className="review-row" key={item.id}><div className="history-icon warning-icon"><TriangleAlert size={22} /></div><div className="review-copy"><h3>{actionLabel(item.kind ?? 'Operacja magazynowa')}</h3><code>{item.id}</code><p>{timestampLabel(item.createdAt)}{item.requestedQuantity ? ` · Żądana ilość: ${quantityLabel(item.requestedQuantity)}` : ''}</p></div><OperationBadge state={item.state} /><button className="button button-secondary" disabled={!online} onClick={() => setSelected(item)}>Sprawdź<ChevronRight size={16} /></button></article>)}</div>}</section>{selected && <ReconcileDialog operation={selected} online={online} onClose={() => setSelected(null)} onSaved={result => { setSelected(null); setLocalRevision(value => value + 1); onOperation(result); onToast('Rozstrzygnięcie zostało zapisane w audycie.'); }} />}</>;
}

function ReconcileDialog({ operation, online, onClose, onSaved }: { operation: Operation; online: boolean; onClose: () => void; onSaved: (op: Operation) => void }) {
  const [resolution, setResolution] = useState<'applied' | 'partial'>('applied'); const [evidence, setEvidence] = useState(''); const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); const evidenceIds = evidence.split(/[\s,;]+/).filter(Boolean).map(Number); if (!evidenceIds.every(id => Number.isSafeInteger(id) && id > 0)) { setError('Podaj dodatnie numery wpisów audytu, oddzielone przecinkami.'); return; } setBusy(true); setError(''); try { onSaved(await api.request<Operation>(`/api/admin/operations/${operation.id}/reconcile`, { method: 'POST', body: { resolution, evidenceIds, reason: reason.trim() } })); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <Dialog title="Uzgodnij wynik" subtitle="Zatwierdzenie wymaga zgodnych dowodów z audytu magazynu." onClose={() => { if (!busy) onClose(); }}><div className="operation-id"><span>Identyfikator operacji</span><code>{operation.id}</code></div><form onSubmit={(event) => void submit(event)}>{error && <Alert>{error}</Alert>}<Field label="Potwierdzony wynik"><select aria-label="Potwierdzony wynik" value={resolution} onChange={e => setResolution(e.target.value as 'applied' | 'partial')} disabled={busy}><option value="applied">Pełne wykonanie operacji</option><option value="partial">Częściowe wykonanie operacji</option></select></Field><Field label="Numery wpisów audytu" hint="Podaj identyfikatory potwierdzających wpisów InvenTree, oddzielone przecinkami."><input aria-label="Numery wpisów audytu" value={evidence} onChange={e => setEvidence(e.target.value)} maxLength={1000} placeholder="np. 125, 126" disabled={busy} /></Field><Field label="Uzasadnienie"><textarea aria-label="Uzasadnienie" value={reason} onChange={e => setReason(e.target.value)} minLength={10} maxLength={1000} rows={3} required disabled={busy} /></Field><Alert kind="info">Gdy nie ma dowodu wykonania, potrzebna jest kontrolowana procedura administracyjna po zatrzymaniu zapisów. Ten formularz nie pozwala uznać operacji za niewykonaną na podstawie samego braku historii.</Alert><div className="dialog-actions"><button type="button" className="button button-secondary" onClick={onClose} disabled={busy}>Anuluj</button><button className="button button-primary" disabled={busy || !online}>{busy ? 'Sprawdzanie dowodów…' : 'Zweryfikuj i rozstrzygnij'}</button></div></form></Dialog>;
}

function UsersPage({ user, online, onToast }: { user: User; online: boolean; onToast: (message: string) => void }) {
  const [editing, setEditing] = useState<User | 'new' | null>(null); const [revision, setRevision] = useState(0);
  const users = useResource<Page<User>>(() => api.request('/api/admin/users'), [revision]);
  return <><PageHeading title="Zespół i uprawnienia" description="Zarządzaj kontami oraz przypisaniem do magazynów." action={<button className="button button-primary" disabled={!online} onClick={() => setEditing('new')}><Plus size={18} />Dodaj pracownika</button>} /><section className="panel"><div className="panel-heading"><div><h2>Konta pracowników</h2><p>Ratownik otrzymuje dostęp do jednego przypisanego magazynu.</p></div><button className="icon-button" aria-label="Odśwież użytkowników" onClick={users.reload} disabled={users.loading}><RefreshCw size={18} /></button></div>{users.error ? <div className="panel-padding"><Alert>{users.error}</Alert></div> : users.loading ? <Spinner label="Pobieranie zespołu…" /> : !users.data?.items.length ? <Empty title="Nie znaleziono kont">Odśwież widok lub skontaktuj się z administratorem systemu.</Empty> : <div className="users-list">{users.data.items.map(item => <article className="user-row" key={item.id}><span className="avatar">{item.login.slice(0, 2).toUpperCase()}</span><div className="user-copy"><h3>{item.login}{item.id === user.id && <span className="you-label">Ty</span>}</h3><p>{roleLabels[item.role]}{item.warehouse ? ` · ${item.warehouse.code}` : ''}</p></div><Badge tone={item.active === false ? 'neutral' : 'success'}>{item.active === false ? 'Nieaktywne' : 'Aktywne'}</Badge><button className="button button-secondary" disabled={!online} onClick={() => setEditing(item)}>Zarządzaj<ChevronRight size={15} /></button></article>)}</div>}</section>{editing && <UserDialog user={editing === 'new' ? null : editing} online={online} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); setRevision(value => value + 1); onToast(editing === 'new' ? 'Konto zostało utworzone. Hasło pracownik ustawi bezpieczną procedurą aktywacji.' : 'Zmiana została zapisana. Poprzednie sesje konta zostały unieważnione.'); }} />}</>;
}

function UserDialog({ user, online, onClose, onSaved }: { user: User | null; online: boolean; onClose: () => void; onSaved: () => void }) {
  const [login, setLogin] = useState(user?.login ?? ''); const [role, setRole] = useState<Role>(user?.role ?? 'medic'); const [warehouseId, setWarehouseId] = useState(user?.warehouse ? String(user.warehouse.id) : ''); const [active, setActive] = useState(user?.active !== false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [resetInfo, setResetInfo] = useState('');
  const warehouses = useResource<Page<Warehouse>>(() => api.request('/api/admin/warehouses'), []);
  async function submit(event: FormEvent) { event.preventDefault(); if (user && !user.version) { setError('Odśwież listę pracowników przed edycją tego konta.'); return; } setBusy(true); setError(''); try { const body = user ? { version: user.version, active, role, warehouseId: role === 'medic' ? Number(warehouseId) : null } : { login: login.trim(), role, ...(role === 'medic' ? { warehouseId: Number(warehouseId) } : {}) }; await api.request(user ? `/api/admin/users/${user.id}` : '/api/admin/users', { method: user ? 'PATCH' : 'POST', body }); onSaved(); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  async function resetPassword() { if (!user) return; setBusy(true); setError(''); try { await api.request(`/api/admin/users/${user.id}/password-reset`, { method: 'POST', body: {} }); setResetInfo('Przyjęto prośbę o reset. Zastosuj ustalony bezpieczny kanał przekazania jednorazowego dostępu. Nie ustawiaj hasła znanego innym osobom.'); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <Dialog title={user ? 'Zarządzaj kontem' : 'Dodaj pracownika'} subtitle={user ? user.login : 'Nowe konto nie otrzymuje domyślnego hasła.'} onClose={() => { if (!busy) onClose(); }}><form onSubmit={(event) => void submit(event)}>{error && <Alert>{error}</Alert>}{resetInfo && <Alert kind="success">{resetInfo}</Alert>}{!user && <Field label="Login pracownika"><input aria-label="Login pracownika" value={login} onChange={e => setLogin(e.target.value)} minLength={3} maxLength={254} autoComplete="off" required disabled={busy} /></Field>}<Field label="Rola"><select aria-label="Rola" value={role} onChange={e => setRole(e.target.value as Role)} disabled={busy}><option value="medic">Ratownik medyczny</option><option value="warehouse_manager">Magazynier</option><option value="admin">Administrator</option></select></Field>{role === 'medic' && <Field label="Przypisany magazyn"><select aria-label="Przypisany magazyn" value={warehouseId} onChange={e => setWarehouseId(e.target.value)} required disabled={busy}><option value="">Wybierz magazyn</option>{warehouses.data?.items.map(item => <option value={item.id} key={item.id}>{item.code} — {item.name}</option>)}</select></Field>}{warehouses.error && <Alert>{warehouses.error}</Alert>}{user && <label className="checkbox-row"><input type="checkbox" checked={active} onChange={e => setActive(e.target.checked)} disabled={busy} /><span><strong>Konto aktywne</strong><small>Wyłączenie konta unieważnia dostęp i dotychczasowe sesje.</small></span></label>}<div className="form-note"><ShieldCheck size={17} /><p>Zmiana roli lub magazynu wymaga ponownego zalogowania pracownika. Nierozstrzygnięte operacje mogą blokować zmianę przydziału.</p></div><div className="dialog-actions"><button className="button button-secondary" type="button" onClick={onClose} disabled={busy}>Anuluj</button><button className="button button-primary" disabled={busy || !online}>{busy ? 'Zapisywanie…' : user ? 'Zapisz zmiany' : 'Utwórz konto'}</button></div></form>{user && <div className="reset-account-block"><h3>Odzyskanie dostępu</h3><p>Reset wymaga potwierdzenia tożsamości pracownika. Poprzednie sesje zostaną unieważnione.</p><button className="text-button" disabled={busy || !online} onClick={() => void resetPassword()}>Rozpocznij reset hasła<ArrowRight size={16} /></button></div>}</Dialog>;
}

function AccountPage({ user, loggingOut, onLogout }: { user: User; loggingOut: boolean; onLogout: () => void }) {
  return <><PageHeading title="Moje konto" description="Twój dostęp do ewidencji magazynowej." /><div className="account-grid"><section className="panel account-panel"><div className="avatar avatar-large">{user.login.slice(0, 2).toUpperCase()}</div><h2>{user.login}</h2><p>{roleLabels[user.role]}</p><div className="account-details"><div><span>Przypisany magazyn</span><strong>{user.warehouse ? `${user.warehouse.code} — ${user.warehouse.name}` : 'Dostęp według roli'}</strong></div><div><span>Zabezpieczenie dostępu</span><strong>Indywidualne konto pracownika</strong></div></div><button className="button button-secondary button-block" onClick={onLogout} disabled={loggingOut}>{loggingOut ? <LoaderCircle className="spin" size={17} /> : <LogOut size={17} />}{loggingOut ? 'Wylogowywanie…' : 'Wyloguj się'}</button></section><section className="panel install-panel"><div className="help-panel-icon"><Smartphone size={25} /></div><h2>Magazyn pod ręką</h2><p>Dodaj MEDAM do ekranu początkowego, aby otwierać aplikację bez szukania jej w przeglądarce.</p><div className="install-instruction"><strong>Android · Chrome</strong><span>Otwórz menu przeglądarki i wybierz „Zainstaluj aplikację” lub „Dodaj do ekranu głównego”.</span></div><div className="install-instruction"><strong>iPhone · Safari</strong><span>Wybierz „Udostępnij”, a następnie „Do ekranu początkowego”.</span></div><div className="form-note"><Wifi size={17} /><p>Logowanie i zapisy wymagają połączenia z serwerem. Aplikacja nie wykonuje rozchodów offline.</p></div></section></div></>;
}
